// Perfil determinístico das colunas — nenhuma IA envolvida.
// Saída: 1 item com estatísticas por coluna, candidatas a agrupamento e outliers (IQR).
const IQR_FACTOR = 1.5;
const LOW_CARDINALITY_MAX = 30;
const TOP_VALUES = 20;

const items = $input.all();
if (!items.length) {
	throw new Error(
		'Nenhuma linha encontrada na planilha. Verifique se o arquivo Excel tem dados e cabeçalho na primeira linha.',
	);
}
const rows = items.map((item) => item.json);

const colNames = [];
for (const row of rows) {
	for (const key of Object.keys(row)) {
		if (!colNames.includes(key)) colNames.push(key);
	}
}
if (!colNames.length) {
	throw new Error('Nenhuma coluna encontrada na planilha.');
}

function parseNumber(value) {
	if (typeof value === 'number') return Number.isFinite(value) ? value : null;
	if (typeof value === 'string') {
		const trimmed = value.trim();
		if (!/^-?\d+(?:[.,]\d+)?$/.test(trimmed)) return null;
		return Number(trimmed.replace(',', '.'));
	}
	return null;
}

function quantile(sorted, q) {
	if (!sorted.length) return null;
	const pos = (sorted.length - 1) * q;
	const base = Math.floor(pos);
	const rest = pos - base;
	if (sorted[base + 1] !== undefined) return sorted[base] + rest * (sorted[base + 1] - sorted[base]);
	return sorted[base];
}

function round4(n) {
	return typeof n === 'number' ? Math.round(n * 10000) / 10000 : n;
}

const columns = colNames.map((name) => {
	const rawValues = rows.map((r) => r[name]);
	const nonNull = rawValues.filter((v) => v !== null && v !== undefined && String(v).trim() !== '');
	const nullCount = rawValues.length - nonNull.length;

	const counts = new Map();
	for (const v of nonNull) {
		const key = String(v);
		counts.set(key, (counts.get(key) || 0) + 1);
	}
	const uniqueCount = counts.size;
	const topValues = [...counts.entries()]
		.sort((a, b) => b[1] - a[1])
		.slice(0, TOP_VALUES)
		.map(([value, count]) => ({ value, count }));

	const numericPairs = [];
	for (let i = 0; i < rows.length; i++) {
		const n = parseNumber(rows[i][name]);
		if (n !== null) numericPairs.push({ value: n, rowIndex: i });
	}
	const isNumeric = nonNull.length > 0 && numericPairs.length >= nonNull.length * 0.9;

	let stats = null;
	let outliers = null;
	if (isNumeric && numericPairs.length) {
		const sorted = numericPairs.map((p) => p.value).sort((a, b) => a - b);
		let sum = 0;
		for (const v of sorted) sum += v;
		const mean = sum / sorted.length;
		let varSum = 0;
		for (const v of sorted) varSum += (v - mean) * (v - mean);
		const q1 = quantile(sorted, 0.25);
		const q3 = quantile(sorted, 0.75);
		const iqr = q3 - q1;
		const lowerBound = q1 - IQR_FACTOR * iqr;
		const upperBound = q3 + IQR_FACTOR * iqr;
		const outlierPairs = numericPairs.filter((p) => p.value < lowerBound || p.value > upperBound);
		stats = {
			min: sorted[0],
			max: sorted[sorted.length - 1],
			mean: round4(mean),
			median: round4(quantile(sorted, 0.5)),
			q1: round4(q1),
			q3: round4(q3),
			std: round4(Math.sqrt(varSum / sorted.length)),
		};
		outliers = {
			lowerBound: round4(lowerBound),
			upperBound: round4(upperBound),
			count: outlierPairs.length,
			samples: outlierPairs.slice(0, 10).map((p) => ({ value: p.value, excelRow: p.rowIndex + 2 })),
		};
	}

	return {
		name,
		type: isNumeric ? 'number' : 'string',
		nullCount,
		uniqueCount,
		lowCardinality: uniqueCount >= 2 && uniqueCount <= LOW_CARDINALITY_MAX,
		topValues,
		stats,
		outliers,
	};
});

const candidateGroupBys = columns.filter((c) => c.lowCardinality).map((c) => c.name);

return [
	{
		json: {
			rowCount: rows.length,
			columnCount: columns.length,
			columns,
			candidateGroupBys,
			sampleRows: rows.slice(0, 5),
			iqrFactor: IQR_FACTOR,
		},
	},
];

