// Valida as sugestões da IA contra as colunas reais (anti-alucinação)
// e monta os campos do formulário de seleção de capítulos.
const aiOutput = $input.first().json.output || {};
const profile = $('Profile Columns').first().json;
const validColumns = new Set((profile.columns || []).map((c) => c.name));

function slugify(text) {
	return (
		String(text)
			.normalize('NFD')
			.replace(/[\u0300-\u036f]/g, '')
			.toLowerCase()
			.replace(/[^a-z0-9]+/g, '-')
			.replace(/^-+|-+$/g, '')
			.slice(0, 40) || 'capitulo'
	);
}

const seen = new Set();
const chapters = [];
for (const raw of aiOutput.suggested_chapters || []) {
	if (!raw || !raw.title || !raw.group_by_column) continue;
	if (!validColumns.has(raw.group_by_column)) continue;
	const id = slugify(raw.id || raw.title);
	if (!id || id === 'outliers' || seen.has(id)) continue;
	seen.add(id);
	chapters.push({
		id,
		title: String(raw.title),
		description: String(raw.description || ''),
		group_by_column: raw.group_by_column,
		columns_covered: (raw.columns_covered || []).filter((c) => validColumns.has(c)),
	});
}

if (!chapters.length) {
	throw new Error(
		'A IA não sugeriu nenhum capítulo válido (todas as sugestões referenciavam colunas inexistentes). Reexecute o workflow ou revise a planilha.',
	);
}

const options = chapters.map((c) => ({
	option: c.id + ' — ' + c.title + ' (agrupado por ' + c.group_by_column + ')',
}));
options.push({ option: 'outliers — Outliers e anomalias (IQR)' });

const formFields = [
	{
		fieldLabel: 'Capítulos',
		fieldType: 'checkbox',
		requiredField: true,
		fieldOptions: { values: options },
	},
	{ fieldLabel: 'Instruções adicionais (opcional)', fieldType: 'textarea' },
];

return [
	{
		json: {
			formFieldsJson: JSON.stringify(formFields),
			plan: { ...aiOutput, suggested_chapters: chapters },
		},
	},
];

