// Gerador determinístico de todos os arquivos da base de conhecimento.
// Todo conteúdo de dados vem direto das linhas da planilha — a IA contribui
// apenas com o system prompt, a arquitetura e os títulos/descrições dos capítulos.
function normalizeArray(value) {
	if (Array.isArray(value)) return value;
	if (value === undefined || value === null || value === '') return [];
	return [value];
}

const rows = $('Extract Rows').all().map((item) => item.json);
const profile = $('Profile Columns').first().json;
const plan = $('Prepare Chapter Form').first().json.plan || {};
const docs = $('Generate Agent Docs').first().json.output || {};
const selection = $('Select Chapters').first().json;

const selectedLabels = normalizeArray(selection['Capítulos']);
const selectedIds = selectedLabels
	.map((label) => String(label).split(' — ')[0].trim())
	.filter(Boolean);
if (!selectedIds.length) {
	throw new Error('Nenhum capítulo foi selecionado no formulário.');
}

const sourceFile =
	$('On form submission').first().json['Caminho do arquivo Excel'] || 'planilha.xlsx';
const generatedAt = new Date().toISOString();

const IQR_FACTOR = profile.iqrFactor || 1.5;
const MAX_GROUPS = 50;
const MAX_ROWS_PER_GROUP = 500;
const MAX_INDEX_TERMS = 1500;

const columnsByName = new Map((profile.columns || []).map((c) => [c.name, c]));
const chaptersById = new Map((plan.suggested_chapters || []).map((c) => [c.id, c]));
const meaningByColumn = new Map((plan.columns || []).map((c) => [c.name, c.meaning || '']));
const allColumnNames = (profile.columns || []).map((c) => c.name);

function stripAccents(text) {
	return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function slugify(text) {
	return (
		stripAccents(text)
			.toLowerCase()
			.replace(/[^a-z0-9]+/g, '-')
			.replace(/^-+|-+$/g, '') || 'secao'
	);
}
function anchorFor(heading) {
	return stripAccents(heading)
		.toLowerCase()
		.replace(/[^a-z0-9\s-]/g, '')
		.trim()
		.replace(/\s+/g, '-');
}
function esc(value) {
	return String(value === undefined || value === null ? '' : value)
		.replace(/\|/g, '\\|')
		.replace(/\r?\n/g, ' ');
}
function fmt(n) {
	return typeof n === 'number' ? String(Math.round(n * 100) / 100) : String(n);
}
function parseNumber(value) {
	if (typeof value === 'number') return Number.isFinite(value) ? value : null;
	if (typeof value === 'string') {
		const trimmed = value.trim();
		if (!/^-?\d+(?:[.,]\d+)?$/.test(trimmed)) return null;
		return Number(trimmed.replace(',', '.'));
	}
	return null;
}
function renderTable(tableRows, cols) {
	const lines = [];
	lines.push('| ' + cols.map(esc).join(' | ') + ' |');
	lines.push('|' + cols.map(() => ' --- ').join('|') + '|');
	for (const r of tableRows) {
		lines.push('| ' + cols.map((c) => esc(r[c])).join(' | ') + ' |');
	}
	return lines.join('\n');
}

const files = [];
const indexChapters = [];
const chunks = [];
const skippedNotes = [];

const normalChapterIds = selectedIds.filter((id) => id !== 'outliers');
const includeOutliers = selectedIds.includes('outliers');

// ---- Capítulos de dados -------------------------------------------------
for (const id of normalChapterIds) {
	const chapter = chaptersById.get(id);
	if (!chapter) {
		skippedNotes.push('Capítulo "' + id + '" não encontrado nas sugestões; ignorado.');
		continue;
	}
	const groupCol = chapter.group_by_column;
	if (!columnsByName.has(groupCol)) {
		skippedNotes.push(
			'Capítulo "' + id + '" ignorado: coluna "' + groupCol + '" não existe na planilha.',
		);
		continue;
	}

	let covered = (chapter.columns_covered || []).filter((c) => columnsByName.has(c));
	if (!covered.length) covered = [...allColumnNames];
	if (!covered.includes(groupCol)) covered = [groupCol, ...covered];
	const numericCovered = covered.filter(
		(c) => c !== groupCol && (columnsByName.get(c) || {}).type === 'number',
	);

	const groupsMap = new Map();
	for (const row of rows) {
		const rawKey = row[groupCol];
		const key =
			rawKey === undefined || rawKey === null || String(rawKey).trim() === ''
				? '(vazio)'
				: String(rawKey);
		if (!groupsMap.has(key)) groupsMap.set(key, []);
		groupsMap.get(key).push(row);
	}
	const groupKeys = [...groupsMap.keys()].sort((a, b) => a.localeCompare(b, 'pt-BR'));

	const fileName = 'capitulo-' + id + '.md';
	const lines = [];
	lines.push('# ' + (chapter.title || id));
	lines.push('');
	lines.push(
		'> Gerado deterministicamente de "' +
			sourceFile +
			'" em ' +
			generatedAt +
			'. Nenhum valor foi inventado por IA.',
	);
	lines.push('');
	if (chapter.description) {
		lines.push('**Descrição (interpretação da IA):** ' + chapter.description);
		lines.push('');
	}
	lines.push('- Coluna de agrupamento: **' + groupCol + '**');
	lines.push('- Grupos: **' + groupKeys.length + '** | Registros no total: **' + rows.length + '**');
	lines.push('- Colunas cobertas: ' + covered.join(', '));
	lines.push('');

	const sections = [];

	if (groupKeys.length > MAX_GROUPS) {
		const maxRows = MAX_ROWS_PER_GROUP * 4;
		const heading = 'Tabela completa ordenada por ' + groupCol;
		const anchor = anchorFor(heading);
		lines.push('## ' + heading);
		lines.push('');
		lines.push(
			'> A coluna "' +
				groupCol +
				'" tem ' +
				groupKeys.length +
				' valores distintos (mais que ' +
				MAX_GROUPS +
				'), então este capítulo usa uma tabela única ordenada em vez de uma seção por grupo.',
		);
		lines.push('');
		const sortedRows = [...rows].sort((a, b) =>
			String(a[groupCol]).localeCompare(String(b[groupCol]), 'pt-BR'),
		);
		lines.push(renderTable(sortedRows.slice(0, maxRows), covered));
		if (sortedRows.length > maxRows) {
			lines.push('');
			lines.push(
				'> Tabela truncada em ' +
					maxRows +
					' de ' +
					sortedRows.length +
					' linhas. Os dados completos estão em dados-rag.json.',
			);
		}
		sections.push({ group: '(tabela única)', anchor, rowCount: rows.length });
		chunks.push({
			id: id + '--tabela-completa',
			chapter: id,
			group: '(tabela única)',
			text: lines.join('\n'),
			metadata: {
				source_file: fileName,
				section_anchor: anchor,
				columns: covered,
				rowCount: rows.length,
				keywords: [groupCol, chapter.title || id],
			},
		});
	} else {
		for (const key of groupKeys) {
			const groupRows = groupsMap.get(key);
			const heading = groupCol + ': ' + key;
			const anchor = anchorFor(heading);
			const sLines = [];
			sLines.push('## ' + heading);
			sLines.push('');
			sLines.push('- Registros: **' + groupRows.length + '**');
			for (const nc of numericCovered) {
				let sum = 0;
				let min = null;
				let max = null;
				let count = 0;
				for (const r of groupRows) {
					const n = parseNumber(r[nc]);
					if (n === null) continue;
					sum += n;
					count += 1;
					if (min === null || n < min) min = n;
					if (max === null || n > max) max = n;
				}
				if (!count) continue;
				sLines.push(
					'- ' +
						nc +
						': soma **' +
						fmt(sum) +
						'** | média **' +
						fmt(sum / count) +
						'** | mín **' +
						fmt(min) +
						'** | máx **' +
						fmt(max) +
						'**',
				);
			}
			sLines.push('');
			sLines.push(renderTable(groupRows.slice(0, MAX_ROWS_PER_GROUP), covered));
			if (groupRows.length > MAX_ROWS_PER_GROUP) {
				sLines.push('');
				sLines.push(
					'> Tabela truncada em ' +
						MAX_ROWS_PER_GROUP +
						' de ' +
						groupRows.length +
						' linhas. Os agregados acima consideram TODAS as linhas do grupo.',
				);
			}
			const sectionMd = sLines.join('\n');
			lines.push(sectionMd);
			lines.push('');
			sections.push({ group: key, anchor, rowCount: groupRows.length });
			chunks.push({
				id: id + '--' + slugify(key),
				chapter: id,
				group: key,
				text: sectionMd,
				metadata: {
					source_file: fileName,
					section_anchor: anchor,
					columns: covered,
					rowCount: groupRows.length,
					keywords: [key, groupCol, chapter.title || id],
				},
			});
		}
	}

	files.push({ fileName, content: lines.join('\n') });
	indexChapters.push({
		id,
		fileName,
		title: chapter.title || id,
		description: chapter.description || '',
		groupCol,
		covered,
		sections,
	});
}

// ---- Capítulo de outliers ----------------------------------------------
if (includeOutliers) {
	const fileName = 'capitulo-outliers.md';
	const lines = [];
	lines.push('# Outliers e anomalias (critério IQR)');
	lines.push('');
	lines.push(
		'> Gerado deterministicamente de "' +
			sourceFile +
			'" em ' +
			generatedAt +
			'. Outlier = valor fora de [Q1 − ' +
			IQR_FACTOR +
			'·IQR, Q3 + ' +
			IQR_FACTOR +
			'·IQR].',
	);
	lines.push('');
	const sections = [];
	let any = false;
	for (const col of profile.columns || []) {
		if (!col.outliers || !col.outliers.count) continue;
		any = true;
		const heading = 'Coluna: ' + col.name;
		const anchor = anchorFor(heading);
		const outRows = [];
		for (let i = 0; i < rows.length; i++) {
			const n = parseNumber(rows[i][col.name]);
			if (n !== null && (n < col.outliers.lowerBound || n > col.outliers.upperBound)) {
				outRows.push({ linha_excel: i + 2, ...rows[i] });
			}
		}
		const sLines = [];
		sLines.push('## ' + heading);
		sLines.push('');
		sLines.push(
			'- Faixa normal: ' +
				fmt(col.outliers.lowerBound) +
				' a ' +
				fmt(col.outliers.upperBound) +
				' | Outliers: **' +
				outRows.length +
				'**',
		);
		sLines.push('');
		sLines.push(renderTable(outRows.slice(0, MAX_ROWS_PER_GROUP), ['linha_excel', ...allColumnNames]));
		if (outRows.length > MAX_ROWS_PER_GROUP) {
			sLines.push('');
			sLines.push('> Tabela truncada em ' + MAX_ROWS_PER_GROUP + ' de ' + outRows.length + ' linhas.');
		}
		const sectionMd = sLines.join('\n');
		lines.push(sectionMd);
		lines.push('');
		sections.push({ group: col.name, anchor, rowCount: outRows.length });
		chunks.push({
			id: 'outliers--' + slugify(col.name),
			chapter: 'outliers',
			group: col.name,
			text: sectionMd,
			metadata: {
				source_file: fileName,
				section_anchor: anchor,
				columns: allColumnNames,
				rowCount: outRows.length,
				keywords: [col.name, 'outlier', 'anomalia', 'IQR'],
			},
		});
	}
	if (!any) {
		lines.push('Nenhum outlier numérico foi detectado pelo critério IQR nesta planilha.');
	}
	files.push({ fileName, content: lines.join('\n') });
	indexChapters.push({
		id: 'outliers',
		fileName,
		title: 'Outliers e anomalias (IQR)',
		description: 'Valores numéricos fora da faixa interquartil esperada.',
		groupCol: '(colunas numéricas)',
		covered: allColumnNames,
		sections,
	});
}

if (!indexChapters.length) {
	throw new Error(
		'Nenhum capítulo pôde ser gerado. Detalhes: ' + (skippedNotes.join(' ') || 'seleção vazia.'),
	);
}

// ---- 02-sumario-busca.md (índice de roteamento para o agente) -----------
const fixedFiles = [
	['00-system-prompt.md', 'System prompt do agente', 'Configuração do agente; não responde perguntas de dados.'],
	['01-arquitetura-do-agente.md', 'Arquitetura do agente', 'Entender o desenho da solução e o fluxo RAG.'],
	['02-sumario-busca.md', 'Sumário de busca (este arquivo)', 'SEMPRE consultar primeiro para achar o arquivo certo.'],
	['dados-rag.json', 'Chunks com metadados para embedding', 'Ingestão em banco vetorial / busca programática.'],
	['gerador_capitulos.py', 'Script Python auditável', 'Reproduzir/auditar os cálculos dos capítulos.'],
];

const sumLines = [];
sumLines.push('# 02 — Sumário de busca');
sumLines.push('');
sumLines.push(
	'> PROTOCOLO DO AGENTE: antes de responder qualquer pergunta, localize aqui o arquivo e a seção correlatos ao termo perguntado. Responda SOMENTE com dados do arquivo indicado, citando arquivo e seção. Se o termo não estiver neste sumário, informe que a base não cobre o assunto.',
);
sumLines.push('');
sumLines.push('Fonte: "' + sourceFile + '" | ' + rows.length + ' registros | gerado em ' + generatedAt);
sumLines.push('');
sumLines.push('## Mapa de arquivos');
sumLines.push('');
sumLines.push('| Arquivo | Conteúdo | Quando usar |');
sumLines.push('| --- | --- | --- |');
for (const [f, what, when] of fixedFiles) {
	sumLines.push('| `' + f + '` | ' + what + ' | ' + when + ' |');
}
for (const ch of indexChapters) {
	sumLines.push(
		'| `' +
			ch.fileName +
			'` | ' +
			esc(ch.title) +
			' (agrupado por ' +
			esc(ch.groupCol) +
			') | Perguntas sobre ' +
			esc(ch.groupCol) +
			' ou ' +
			esc(ch.title.toLowerCase()) +
			' |',
	);
}
sumLines.push('');

for (const ch of indexChapters) {
	sumLines.push('## `' + ch.fileName + '` — ' + ch.title);
	sumLines.push('');
	if (ch.description) sumLines.push(ch.description);
	const keywords = new Set([ch.groupCol, ch.title]);
	for (const c of ch.covered) {
		keywords.add(c);
		const meaning = meaningByColumn.get(c);
		if (meaning) keywords.add(meaning);
	}
	sumLines.push('');
	sumLines.push('- Palavras-chave: ' + [...keywords].map(esc).join('; '));
	sumLines.push('- Seções (' + ch.sections.length + '):');
	for (const s of ch.sections) {
		sumLines.push('  - [' + esc(s.group) + '](' + ch.fileName + '#' + s.anchor + ') — ' + s.rowCount + ' registros');
	}
	sumLines.push('');
}

sumLines.push('## Índice invertido (termo → arquivo → seção)');
sumLines.push('');
sumLines.push('| Termo | Arquivo | Seção (âncora) |');
sumLines.push('| --- | --- | --- |');
let termCount = 0;
for (const ch of indexChapters) {
	for (const s of ch.sections) {
		if (termCount >= MAX_INDEX_TERMS) break;
		sumLines.push('| ' + esc(s.group) + ' | `' + ch.fileName + '` | #' + s.anchor + ' |');
		termCount += 1;
	}
}
if (termCount >= MAX_INDEX_TERMS) {
	sumLines.push('');
	sumLines.push('> Índice truncado em ' + MAX_INDEX_TERMS + ' termos. A lista completa está em dados-rag.json (search_index).');
}
if (skippedNotes.length) {
	sumLines.push('');
	sumLines.push('## Avisos de geração');
	sumLines.push('');
	for (const note of skippedNotes) sumLines.push('- ' + note);
}

// ---- 00-system-prompt.md e 01-arquitetura-do-agente.md -------------------
const allFileNames = [
	'00-system-prompt.md',
	'01-arquitetura-do-agente.md',
	'02-sumario-busca.md',
	...indexChapters.map((c) => c.fileName),
	'dados-rag.json',
	'gerador_capitulos.py',
];

let systemPrompt = String(docs.system_prompt_md || '').trim();
if (!systemPrompt) {
	systemPrompt = '# System prompt do agente\n\n(A IA não retornou conteúdo; siga o protocolo abaixo.)';
}
systemPrompt +=
	'\n\n---\n\n## Protocolo de busca obrigatório (gerado automaticamente)\n\n' +
	'1. Consulte SEMPRE `02-sumario-busca.md` primeiro e localize o arquivo/seção correlato ao termo da pergunta.\n' +
	'2. Responda usando SOMENTE o conteúdo do(s) arquivo(s) de capítulo indicados pelo sumário.\n' +
	'3. Cite o arquivo e a seção usados na resposta (ex.: `capitulo-regiao.md#regiao-sul`).\n' +
	'4. Se o termo não constar no sumário, responda que a base de conhecimento não cobre o assunto. Nunca invente valores.\n' +
	'\n### Inventário de arquivos\n\n' +
	allFileNames.map((f) => '- `' + f + '`').join('\n') +
	'\n';

let architecture = String(docs.architecture_md || '').trim();
if (!architecture) {
	architecture = '# Arquitetura do agente\n\n(A IA não retornou conteúdo.)';
}
architecture +=
	'\n\n---\n\n## Inventário RAG (gerado automaticamente)\n\n```json\n' +
	JSON.stringify(
		{
			generated_at: generatedAt,
			source_file: sourceFile,
			row_count: rows.length,
			chunk_count: chunks.length,
			files: allFileNames,
			chapters: indexChapters.map((c) => ({
				id: c.id,
				file: c.fileName,
				title: c.title,
				group_by: c.groupCol,
				sections: c.sections.length,
			})),
		},
		null,
		2,
	) +
	'\n```\n';

// ---- dados-rag.json -------------------------------------------------------
const searchIndex = [];
for (const ch of indexChapters) {
	for (const s of ch.sections) {
		searchIndex.push({
			keywords: [s.group, ch.groupCol, ch.title].filter(Boolean),
			file: ch.fileName,
			section: s.anchor,
			rowCount: s.rowCount,
		});
	}
}
const ragJson = {
	generated_at: generatedAt,
	source_file: sourceFile,
	row_count: rows.length,
	chapters: indexChapters.map((c) => ({
		id: c.id,
		file: c.fileName,
		title: c.title,
		description: c.description,
		group_by: c.groupCol,
		columns: c.covered,
	})),
	search_index: searchIndex,
	chunks,
};

// ---- gerador_capitulos.py -------------------------------------------------
const pyConfig = {
	source_file: sourceFile,
	generated_at: generatedAt,
	iqr_factor: IQR_FACTOR,
	max_groups: MAX_GROUPS,
	max_rows_per_group: MAX_ROWS_PER_GROUP,
	include_outliers: includeOutliers,
	chapters: indexChapters
		.filter((c) => c.id !== 'outliers')
		.map((c) => ({
			id: c.id,
			title: c.title,
			description: c.description,
			group_by_column: c.groupCol,
			columns_covered: c.covered,
		})),
};
const pyConfigJson = JSON.stringify(pyConfig, null, 2).replace(/'/g, '\\u0027');

const py = [
	'#!/usr/bin/env python3',
	'# -*- coding: utf-8 -*-',
	'"""Gerador deterministico dos capitulos .md da base de conhecimento.',
	'',
	'Reproduz, de forma auditavel, os calculos feitos pelo workflow n8n',
	'"Excel -> Markdown RAG": agrupamentos, agregados (soma/media/min/max)',
	'e deteccao de outliers por IQR. Nenhuma IA e usada aqui.',
	'',
	'Uso:',
	'    python gerador_capitulos.py caminho/para/planilha.xlsx [pasta_saida]',
	'',
	'Requisitos: pandas, openpyxl',
	'"""',
	'import json',
	'import math',
	'import os',
	'import sys',
	'import unicodedata',
	'',
	'import pandas as pd',
	'',
	"CONFIG = json.loads(r'''__PY_CONFIG__''')",
	'',
	"IQR_FACTOR = CONFIG['iqr_factor']",
	"MAX_ROWS_PER_GROUP = CONFIG['max_rows_per_group']",
	"MAX_GROUPS = CONFIG['max_groups']",
	'',
	'',
	'def strip_accents(text):',
	"    return ''.join(",
	"        ch for ch in unicodedata.normalize('NFD', str(text))",
	"        if unicodedata.category(ch) != 'Mn'",
	'    )',
	'',
	'',
	'def slugify(text):',
	'    out = []',
	'    prev_dash = False',
	'    for ch in strip_accents(text).lower():',
	'        if ch.isalnum():',
	'            out.append(ch)',
	'            prev_dash = False',
	'        elif not prev_dash:',
	"            out.append('-')",
	'            prev_dash = True',
	"    return ''.join(out).strip('-') or 'secao'",
	'',
	'',
	'def esc(value):',
	"    if value is None or (isinstance(value, float) and math.isnan(value)):",
	"        return ''",
	"    return str(value).replace('|', '\\\\|').replace('\\n', ' ')",
	'',
	'',
	'def render_table(df, cols):',
	"    lines = ['| ' + ' | '.join(esc(c) for c in cols) + ' |']",
	"    lines.append('|' + '|'.join(' --- ' for _ in cols) + '|')",
	'    for _, row in df.iterrows():',
	"        lines.append('| ' + ' | '.join(esc(row.get(c, '')) for c in cols) + ' |')",
	"    return '\\n'.join(lines)",
	'',
	'',
	'def fmt(n):',
	'    return str(round(float(n) * 100) / 100)',
	'',
	'',
	'def build_chapter(df, chapter, out_dir):',
	"    group_col = chapter['group_by_column']",
	"    covered = [c for c in chapter['columns_covered'] if c in df.columns] or list(df.columns)",
	'    if group_col not in covered:',
	'        covered = [group_col] + covered',
	'    numeric = [',
	'        c for c in covered',
	'        if c != group_col and pd.api.types.is_numeric_dtype(pd.to_numeric(df[c], errors="coerce"))',
	'        and pd.to_numeric(df[c], errors="coerce").notna().mean() >= 0.9',
	'    ]',
	"    lines = ['# ' + chapter['title'], '']",
	"    if chapter.get('description'):",
	"        lines += ['**Descrição:** ' + chapter['description'], '']",
	"    lines += ['- Coluna de agrupamento: **' + group_col + '**', '']",
	'    groups = sorted(df.groupby(df[group_col].fillna("(vazio)").astype(str)), key=lambda kv: kv[0])',
	'    if len(groups) > MAX_GROUPS:',
	"        lines += ['## Tabela completa ordenada por ' + group_col, '']",
	'        ordered = df.sort_values(by=group_col, key=lambda s: s.astype(str))',
	'        lines.append(render_table(ordered.head(MAX_ROWS_PER_GROUP * 4), covered))',
	'    else:',
	'        for key, gdf in groups:',
	"            lines += ['## ' + group_col + ': ' + str(key), '', '- Registros: **' + str(len(gdf)) + '**']",
	'            for nc in numeric:',
	'                nums = pd.to_numeric(gdf[nc], errors="coerce").dropna()',
	'                if nums.empty:',
	'                    continue',
	"                lines.append('- ' + nc + ': soma **' + fmt(nums.sum()) + '** | média **' + fmt(nums.mean()) + '** | mín **' + fmt(nums.min()) + '** | máx **' + fmt(nums.max()) + '**')",
	"            lines.append('')",
	'            lines.append(render_table(gdf.head(MAX_ROWS_PER_GROUP), covered))',
	'            if len(gdf) > MAX_ROWS_PER_GROUP:',
	"                lines += ['', '> Tabela truncada em ' + str(MAX_ROWS_PER_GROUP) + ' de ' + str(len(gdf)) + ' linhas.']",
	"            lines.append('')",
	"    path = os.path.join(out_dir, 'capitulo-' + chapter['id'] + '.md')",
	"    with open(path, 'w', encoding='utf-8') as fh:",
	"        fh.write('\\n'.join(lines))",
	'    return path',
	'',
	'',
	'def build_outliers(df, out_dir):',
	"    lines = ['# Outliers e anomalias (critério IQR)', '']",
	'    for col in df.columns:',
	'        nums = pd.to_numeric(df[col], errors="coerce")',
	'        if nums.notna().mean() < 0.9 or nums.dropna().empty:',
	'            continue',
	'        q1, q3 = nums.quantile(0.25), nums.quantile(0.75)',
	'        iqr = q3 - q1',
	'        lower, upper = q1 - IQR_FACTOR * iqr, q3 + IQR_FACTOR * iqr',
	'        mask = (nums < lower) | (nums > upper)',
	'        if not mask.any():',
	'            continue',
	"        lines += ['## Coluna: ' + col, '',",
	"                  '- Faixa normal: ' + fmt(lower) + ' a ' + fmt(upper) + ' | Outliers: **' + str(int(mask.sum())) + '**', '']",
	'        out_df = df[mask].copy()',
	"        out_df.insert(0, 'linha_excel', [i + 2 for i in df.index[mask]])",
	"        lines.append(render_table(out_df.head(MAX_ROWS_PER_GROUP), list(out_df.columns)))",
	"        lines.append('')",
	"    path = os.path.join(out_dir, 'capitulo-outliers.md')",
	"    with open(path, 'w', encoding='utf-8') as fh:",
	"        fh.write('\\n'.join(lines))",
	'    return path',
	'',
	'',
	'def main():',
	"    src = sys.argv[1] if len(sys.argv) > 1 else CONFIG['source_file']",
	"    out_dir = sys.argv[2] if len(sys.argv) > 2 else '.'",
	'    os.makedirs(out_dir, exist_ok=True)',
	'    df = pd.read_excel(src)',
	'    written = []',
	"    for chapter in CONFIG['chapters']:",
	'        written.append(build_chapter(df, chapter, out_dir))',
	"    if CONFIG['include_outliers']:",
	'        written.append(build_outliers(df, out_dir))',
	"    print('Arquivos gerados:')",
	'    for path in written:',
	"        print('  ' + path)",
	'',
	'',
	"if __name__ == '__main__':",
	'    main()',
	'',
]
	.join('\n')
	.replace('__PY_CONFIG__', pyConfigJson);

// ---- Monta a lista final na ordem de leitura -----------------------------
const orderedFiles = [
	{ fileName: '00-system-prompt.md', content: systemPrompt },
	{ fileName: '01-arquitetura-do-agente.md', content: architecture },
	{ fileName: '02-sumario-busca.md', content: sumLines.join('\n') },
	...files,
	{ fileName: 'dados-rag.json', content: JSON.stringify(ragJson, null, 2) },
	{ fileName: 'gerador_capitulos.py', content: py },
];

return orderedFiles.map((f) => ({ json: f }));
